RELEVANCE_THRESHOLD = 0.5

# --- from notebook cell 1 ---
def retrieve_with_confidence(query: str) -> tuple[list, float]:
    """Returns retrieved docs and the top chunk's confidence score.
    Uses cosine similarity to score from your vectore store.
    """

    # creating a native llamaindex retriever from my initialized index
    retriever = index.as_retriever(similarity_top_k = 4)
    results = retriever.retrieve(query)

    # reults is a list of (document, score) tuples
    # lower score = more similar in FAISS  (L2 distance); invert if needed
    # For Cosine similarity stores, higher = better

    if not results:
        return [], 0.0


    top_score = float(results[0].score) if results[0].score is not None else 0.0

    print(f"📣 Top retrieval score : {top_score:.3f} (threshold: {RELEVANCE_THRESHOLD})")
    return results, top_score

# --- from notebook cell 1 ---
def format_chunks(docs: list) -> str:
    return "\n\n---\n\n".join([doc.node.get_content() for doc in docs])


def source_references(docs: list) -> list[dict]:
    """Return safe, displayable references without exposing local file paths."""
    references = []
    seen = set()
    for item in docs or []:
        node = getattr(item, "node", None)
        metadata = getattr(node, "metadata", {}) or {}
        normalized = {
            re.sub(r"[^a-z0-9]", "", str(key).lower()): value
            for key, value in metadata.items()
        }
        title = next((normalized.get(key) for key in
                      ("filename", "sourcename", "documentname", "title", "name")
                      if normalized.get(key)), None)
        if title is None:
            raw_path = next((normalized.get(key) for key in ("filepath", "source")
                             if normalized.get(key)), None)
            title = str(raw_path).replace("\\", "/").rsplit("/", 1)[-1] if raw_path else None
        if title is None:
            continue
        title = str(title).replace("\\", "/").rsplit("/", 1)[-1].strip()
        if not title:
            continue
        page = next((normalized.get(key) for key in
                     ("pagelabel", "pagenumber", "page", "pdfpage", "pagenum",
                      "pageno", "locpagenumber")
                     if normalized.get(key) is not None), None)
        reference = {"title": title}
        if page is not None:
            reference["page"] = str(page)
        key = (title.casefold(), reference.get("page"))
        if key not in seen:
            seen.add(key)
            references.append(reference)
    return references

