VISUAL_SCORE_THRESHOLD = 0.650

# --- from notebook cell 27 ---
def best_visual_match(question: str):
    sims = VISUAL_MATRIX @ _embed_query(question)
    i = int(np.argmax(sims))
    return VISUAL_INDEX[i], float(sims[i])

# --- from notebook cell 27 ---
def visual_gate(question: str):
    if not VISUAL_INTENT.search(question):
        return False, {"keyword_hit": False, "best_label": None, "best_score": None}
    rec, score = best_visual_match(question)
    return score >= VISUAL_SCORE_THRESHOLD, {"keyword_hit": True, "best_label": rec["label"], "best_score": score}

