def route_after_classify(state: RAGState) -> Literal["decompose_and_retrieve_node", "retrieve_node"]:
    if state["classification"] == "COMPLEX" and detect_multihop(state["question"]):
        print("  → Edge: multi-hop detected → decompose_and_retrieve_node")
        return "decompose_and_retrieve_node"
    print("  → Edge: single-hop → retrieve_node (unchanged path)")
    return "retrieve_node"

# --- from notebook cell 29 ---
def visual_retrieve_node(state: RAGState) -> dict:
    print(f"\n[NODE: visual_retrieve]")
    rec, score = best_visual_match(state["question"])

    scan = scan_vision_text(rec["description"])    # read-time re-scan: the index is a file on disk
    if scan["status"] != "clean":
        print(f"  🚨 Page {rec['page_number']} description failed the read-time scan "
              f"({scan['status']}): {scan['reason']}")
        return {"context": "No relevant content found.",
                "retrieval_source": "visual_index", "retrieval_score": 0.0,
                "sources": []}

    VISUAL_ROUTE_LOG.append({"event": "visual_node_ran", "page": rec["page_number"], "score": score})
    print(f"  → PDF page {rec['page_number']} ({rec['label']}), similarity {score:.3f}")
    return {"context": build_context(rec),
            "retrieval_source": "visual_index", "retrieval_score": score,
            "sources": [{"title": str(rec.get("label") or "Visual document"),
                         "page": str(rec.get("page_number"))}]}

# --- from notebook cell 29 ---
def route_after_classify_visual(state: RAGState):
    if state.get("classification") != "UNKNOWN":
        use_visual, info = visual_gate(state["question"])
        VISUAL_ROUTE_LOG.append({"question": state["question"][:60], "routed_visual": use_visual, **info})
        if use_visual:
            print(f"  → Edge: chart question matching an indexed page "
                  f"({info['best_label']}, {info['best_score']:.3f}) → visual_retrieve_node")
            return "visual_retrieve_node"
    return route_after_classify(state)

# --- from notebook cell 29 ---
def _timed_node(name: str, node):
    """Log per-node latency so slow model and dependency steps can be isolated."""
    def timed(state: RAGState):
        started = time.perf_counter()
        outcome = "ok"
        try:
            return node(state)
        except Exception as exc:
            outcome = "error"
            logger.warning(
                "rag_pipeline_stage_failed stage=%s error_type=%s request_id=%s",
                name,
                type(exc).__name__,
                _pipeline_request_id() or "-",
            )
            raise
        finally:
            elapsed_ms = (time.perf_counter() - started) * 1000
            logger.info(
                "rag_pipeline_stage_timing stage=%s elapsed_ms=%.1f outcome=%s request_id=%s",
                name,
                elapsed_ms,
                outcome,
                _pipeline_request_id() or "-",
            )

    return timed


def _pipeline_request_id() -> Optional[str]:
    """Read the monitoring request ID when monitoring is enabled, without requiring it."""
    try:
        from monitoring import CURRENT

        record = CURRENT.get()
        return record.rid if record is not None else None
    except (ImportError, AttributeError):
        return None


def build_visual_routed_graph(db_path: str = DB_PATH):
    conn = sqlite3.connect(db_path, check_same_thread=False)
    checkpointer = SqliteSaver(conn)
    graph = StateGraph(RAGState)

    nodes = {
        "rate_limit_check_node": rate_limit_check_node,
        "load_profile_node": load_profile_node,
        "classify_node": classify_node,
        "retrieve_node": retrieve_node,
        "visual_retrieve_node": visual_retrieve_node,
        "decompose_and_retrieve_node": decompose_and_retrieve_node,
        "check_sufficiency_node": check_sufficiency_node,
        "reformulate_node": reformulate_node,
        "generate_node": generate_node,
        "error_log_node": error_log_node,
        "fallback_generate_node": fallback_generate_node,
        "review_node": review_node,
        "rewrite_node": rewrite_node,
        "output_validation_node": output_validation_node,
        "save_memory_node": save_memory_node,
        "summarize_and_trim_node": summarize_and_trim_node,
        "extract_facts_node": extract_facts_node,
        "save_profile_node": save_profile_node,
        "extract_graph_entity_node": extract_graph_entity_node,
        "save_graph_entity_node": save_graph_entity_node,
    }
    for name, node in nodes.items():
        graph.add_node(name, _timed_node(name, node))

    graph.set_entry_point("rate_limit_check_node")
    graph.add_conditional_edges("rate_limit_check_node", route_after_rate_limit,
        {"load_profile_node": "load_profile_node", "__end__": END})
    graph.add_edge("load_profile_node", "classify_node")

    # CHANGED: the router now has a third destination
    graph.add_conditional_edges("classify_node", route_after_classify_visual,
        {"decompose_and_retrieve_node": "decompose_and_retrieve_node",
         "retrieve_node": "retrieve_node",
         "visual_retrieve_node": "visual_retrieve_node"})
    graph.add_edge("visual_retrieve_node", "check_sufficiency_node")      # NEW: bad pick can fall back via reformulate_node -> retrieve_node

    graph.add_edge("decompose_and_retrieve_node", "generate_node")
    graph.add_edge("retrieve_node", "check_sufficiency_node")
    graph.add_edge("reformulate_node", "retrieve_node")
    graph.add_edge("rewrite_node", "generate_node")
    graph.add_edge("error_log_node", "fallback_generate_node")
    graph.add_edge("fallback_generate_node", "review_node")
    graph.add_conditional_edges("generate_node", route_after_generate,
        {"review_node": "review_node", "error_log_node": "error_log_node"})
    graph.add_conditional_edges("check_sufficiency_node", route_after_sufficiency,
        {"generate_node": "generate_node", "reformulate_node": "reformulate_node"})
    graph.add_conditional_edges("review_node", route_after_review,
        {"rewrite_node": "rewrite_node", "__end__": "output_validation_node"})
    graph.add_edge("output_validation_node", "save_memory_node")
    graph.add_edge("save_memory_node", "summarize_and_trim_node")
    graph.add_edge("summarize_and_trim_node", "extract_facts_node")
    graph.add_edge("extract_facts_node", "save_profile_node")
    graph.add_edge("save_profile_node", "extract_graph_entity_node")
    graph.add_edge("extract_graph_entity_node", "save_graph_entity_node")
    graph.add_edge("save_graph_entity_node", END)

    return graph.compile(checkpointer=checkpointer)

